style.css:
@-moz-document domain("paramountplus.com"), domain("www.paramountplus.com"), domain("play.paramountplus.com") {
/* ================= TEXT & BUTTONS ================= */
  a, button, .btn, h1, h2, h3, h4, h5, h6, span, p, div {
    color: #ff3399 !important;
  }

  button, .btn {
    background-color: #ff66b2 !important;
    border: 2px solid #ff3399 !important;
    color: #ffffff !important;
    border-radius: 12px !important;
    box-shadow: 0 0 10px rgba(255, 105, 180, 0.5) !important;
    transition: transform 0.15s ease, background 0.15s ease !important;
  }

  button:hover, .btn:hover {
    background-color: #cc0066 !important;
    transform: scale(1.05) !important;
  }

  /* ================= HEADINGS GLOW ================= */
  h1, h2, h3, h4, h5, h6, .title, .headline {
    text-shadow: 0 0 6px #ff66b2, 0 0 12px #ff3399 !important;
  }

  /* ================= SCROLLBAR ================= */
  ::-webkit-scrollbar {
    width: 12px !important;
  }
  ::-webkit-scrollbar-track {
    background: rgba(255, 182, 193, 0.2) !important;
  }
  ::-webkit-scrollbar-thumb {
    background: #ff3399 !important;
    border-radius: 10px !important;
    border: 2px solid #ffcce5 !important;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #cc0066 !important;
  }
}
